import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimDueCents, useClaims } from '../claims/useClaims';
import { gradeOn, usePeople } from '../people/usePeople';
import { periodOf, usePeriods } from '../periods/usePeriods';
import { claimRateOn, showDue, useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { downloadCsv } from './csv';

/**
 * Downloads the claims as a CSV file: a header line, then one line per claim, people in list order
 * (retired people included, shown or not) and each person's claims oldest first, with the number,
 * date, amount, due, status and period as each claim row shows them. Quoted and ended as the people
 * export.
 */
function ExportClaims({ sheet }: { user: string; sheet: string }) {
  const { data: people = [] } = usePeople(sheet);
  const { data: all = [] } = useClaims(sheet);
  const { data: rates = [] } = useRates(sheet);
  const { data: periods = [] } = usePeriods(sheet);
  const floor = useFloor(sheet);
  const lateBy = useLate(sheet);

  const download = () => {
    const lines = [['person', 'number', 'date', 'amount', 'due', 'status', 'period']];
    for (const p of people) {
      // Claims come newest first: reversed, oldest first.
      const claims = all.filter((c) => c.personId === p.id).reverse();
      for (const c of claims) {
        lines.push([
          p.name,
          c.number ?? '',
          c.date,
          c.amount,
          showDue(claimDueCents(c, floor, claimRateOn(rates, gradeOn(p, c.date), c), lateBy)),
          c.status,
          periodOf(periods, c.dueBy)?.name ?? '',
        ]);
      }
    }
    downloadCsv(lines, `claims-${sheet}.csv`);
  };

  return (
    <p>
      <button type="button" data-testid="export-claims" onClick={download}>
        Export claims (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanels.fill({ order: 12, Component: ExportClaims });
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { usePools } from '../pools/usePools';
import { downloadCsv } from './csv';

/**
 * Downloads the pools as a CSV file: a header line, then one line per member, pools in the order
 * added and each pool's members in the order added, a member that is another pool as pool:<name>,
 * with the share and the cut as the pool row shows them (the cut empty when none). Quoted and ended
 * as the people export.
 */
function ExportPools({ sheet }: { user: string; sheet: string }) {
  const { refetch } = usePools(sheet);

  // Re-read first, so the file holds the cuts as they stand (and the pool rows show the same).
  const download = async () => {
    const { data: pools = [] } = await refetch();
    const lines = [['pool', 'member', 'share', 'cut']];
    for (const p of pools) {
      for (const m of p.members) {
        lines.push([p.name, m.pool !== null ? `pool:${m.pool}` : m.name, m.share, m.cut ?? '']);
      }
    }
    downloadCsv(lines, `pools-${sheet}.csv`);
  };

  return (
    <p>
      <button type="button" data-testid="export-pools" onClick={() => void download()}>
        Export pools (CSV)
      </button>
    </p>
  );
}

